package es.riegocerca.maps;
import android.Manifest;import android.app.Activity;import android.content.*;import android.content.pm.PackageManager;import android.net.Uri;import android.os.Bundle;import android.webkit.*;import android.widget.Toast;
public class MainActivity extends Activity{WebView w;ValueCallback<Uri[]> files;GeolocationPermissions.Callback geo;String origin;static final int LOC=7,FILE=8;public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);setContentView(w);WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setGeolocationEnabled(true);s.setAllowFileAccess(true);s.setAllowContentAccess(true);w.addJavascriptInterface(new MapsBridge(this),"AndroidMaps");w.setWebViewClient(new WebViewClient(){public boolean shouldOverrideUrlLoading(WebView v,String u){try{if(u.startsWith("https://wa.me/")||u.startsWith("https://earth.google.com/")){Intent i=new Intent(Intent.ACTION_VIEW,Uri.parse(u));if(u.contains("earth.google.com"))i.setPackage("com.google.earth");try{startActivity(i);}catch(Exception e){i.setPackage(null);startActivity(i);}return true;}}catch(Exception e){}return false;}});w.setWebChromeClient(new WebChromeClient(){public void onGeolocationPermissionsShowPrompt(String o,GeolocationPermissions.Callback c){origin=o;geo=c;if(checkSelfPermission(Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED||checkSelfPermission(Manifest.permission.ACCESS_COARSE_LOCATION)==PackageManager.PERMISSION_GRANTED){c.invoke(o,true,true);geo=null;}else requestPermissions(new String[]{Manifest.permission.ACCESS_FINE_LOCATION,Manifest.permission.ACCESS_COARSE_LOCATION},LOC);}public boolean onShowFileChooser(WebView v,ValueCallback<Uri[]> c,FileChooserParams p){files=c;try{startActivityForResult(p.createIntent(),FILE);return true;}catch(Exception e){files=null;return false;}}});w.loadUrl("file:///android_asset/index.html");}public void onRequestPermissionsResult(int r,String[] p,int[] g){super.onRequestPermissionsResult(r,p,g);if(r==LOC&&geo!=null){boolean ok=false;for(int x:g)ok|=x==PackageManager.PERMISSION_GRANTED;geo.invoke(origin,ok,true);geo=null;}}}
